/**
 * Vercel build step: write config.js from AAS_API_BASE env.
 * Local / Railway same-origin: leave AAS_API_BASE unset → empty string.
 */
const fs = require("fs");
const path = require("path");

const base = String(process.env.AAS_API_BASE || "")
  .trim()
  .replace(/\/$/, "");

const out = path.join(__dirname, "config.js");
const body =
  "// Generated by inject-api-base.js (Vercel build) or committed default.\n" +
  `window.AAS_API_BASE = ${JSON.stringify(base)};\n`;

fs.writeFileSync(out, body, "utf8");
console.log(
  `[inject-api-base] AAS_API_BASE = ${base ? base : "(same-origin / empty)"}`,
);
